Method.Implementation:
 SET myquery = 6

 //Data is stored in DB as GMT
 SET zonesave=$ZTIMEZONE
 set $ZTIMEZONE = 0
 set dtTm = $HOROLOG

 set lastRun = $GET(^ResendService(..SourceComp _ "-" _ ..TargetComp))

 if (..NumOfDays > 0)
 {

 	if (lastRun '= "")
	 {
		set lastHOROLOG = $ZDATETIMEH(lastRun, 3, 1)
 		set lastRun = $ZDATETIME($PIECE(dtTm, ",", 1) - ..NumOfDays _","_ $PIECE(lastHOROLOG, ",", 2), 3, 1)
	 }
	 else
	 {
		 set lastRun = $ZDATETIME($PIECE(dtTm, ",", 1) - ..NumOfDays _","_ 0, 3, 1)
	 }
 	set currentDtTm = $ZDATETIME($PIECE(dtTm, ",", 1) - ..NumOfDays _","_ $PIECE(dtTm, ",", 2), 3, 1)


	SET myquery(6) = " and mh.TimeCreated BETWEEN '" _ lastRun _ "' AND '"  _ currentDtTm _ "'"
	$$$TRACE(myquery(6))
 }
 else
 {
	 if (lastRun '= "")
	 {		 
		 set currentDtTm = $ZDATETIME(dtTm,3, 1)
		 SET myquery(6) = " and mh.TimeCreated BETWEEN '" _ lastRun _ "'AND '" _ currentDtTm _ "'"		 
	 }
	 else
	 {
		 // From mid night 
		 set currentDtTm = $ZDATE(dtTm,3)
		 SET myquery(6) = " and mh.TimeCreated >=  '" _ currentDtTm _ " 00:00:00'"
	 }
 }

 SET myquery(1) = " select mh.ID AS tMsgId, RawContent AS hlMsg "
 SET myquery(2) = " from  Ens.MessageHeader mh, EnsLib_HL7.Message hl"
 SET myquery(3) = " where SourceConfigName =  ? "
 SET myquery(4) = " and TargetConfigName = ? "  
 set myquery(5) = " and mh.MessageBodyId = hl.ID"

 // Set timezone back to local
 set $ZTIMEZONE = zonesave 

  $$$TRACE(DateRange)
 set fileName = ..SourceComp _"." _ ..TargetComp _ "-" _ $ZDATETIME(dtTm,3,7)
 set ^ResendService(..SourceComp _ "-" _ ..TargetComp) = $ZDATETIME(dtTm,3, 1)

  SET tStatement = ##class(%SQL.Statement).%New()
  SET qStatus = tStatement.%Prepare(.myquery)
    IF qStatus'=1 { $$$LOGERROR( "%Prepare failed:" _ qStatus) return qStatus}
  SET rset = tStatement.%Execute(..SourceComp, ..TargetComp)
  IF rset.%SQLCODE=0 { $$$TRACE("Created a query") }
  ELSEIF rset.%SQLCODE=-361 { $$$LOGERROR("Query exists: " _ rset.%Message) }
  ELSE { $$$LOGERROR("CREATE QUERY error: " _ rset.%SQLCODE_", "_rset.%Message)   return rset.%SQLCODE}

  Set num = 1
   WHILE rset.%Next() {
     set tMsgId = rset.tMsgId

     $$$TRACE( "Message: " _ tMsgId)

     	Set tSC = $$$OK

	Try {

		Set file=##class(%Library.File).%New(..DestDirectory _ fileName _ "-" _ num _ ".rec")

    	Do file.Open("WS:/APPEND")

    	Do file.WriteLine(rset.hlMsg)
    	Do file.Close()
    	set num = num + 1

	}
	Catch (ex) {
		Set tSC = ex.AsStatus()
	}
	If $$$ISERR(tSC) {
		$$$LOGERROR( $system.Status.GetErrorText(tSC))
		return tSC
	}



   }

   return $$$OK
